/// Official Google Authenticator 2FA SVG logo.
#[component]
pub fn TwoFactorLogo(#[props(default = 28)] size: u32) -> Element {
    let html = render_svg(SVG_BRAND_TWOFA, size, size);
    rsx! {
        span {
            class: "brand-badge cw-brand-float",
            "data-brand": "2fa",
            "aria-hidden": "true",
            dangerous_inner_html: "{html}",
        }
    }
}

