/// Official 4x3 vector SVG flag for all 197 world languages (served from /flags/{cc}.svg).
#[component]
pub fn LanguageFlagLogo(code: String, #[props(default = 22)] size: u32) -> Element {
    let h = ((size as f32) * 0.75).round() as u32;
    let flag = crate::i18n::flag_code(&code);
    rsx! {
        span {
            class: "lang-flag-badge",
            "data-lang-flag": "{code}",
            "aria-hidden": "true",
            img {
                class: "lang-flag-img",
                src: "/flags/{flag}.svg",
                width: "{size}",
                height: "{h}",
                loading: "lazy",
                decoding: "async",
                alt: "",
            }
        }
    }
}
